SELECT * FROM ( SELECT ALLOCATION_ID as "allocationId", ALLOCATION_NO as "allocationNo", ALLOCATION_TYPE as "allocationType", ALLOCATION_PERIOD as "allocationPeriod", TOTAL_AMOUNT as "totalAmount", ALLOCATED_AMOUNT as "allocatedAmount", REMAINING_AMOUNT as "remainingAmount", ALLOCATION_STATUS as "allocationStatus", ALLOCATION_DATE as "allocationDate", ALLOCATION_RULE as "allocationRule", CREATE_TIME as "createTime", ROW_NUMBER() OVER (ORDER BY CREATE_TIME DESC) as rn FROM T_REVENUE_ALLOCATION WHERE IS_DELETED = 0 AND TENANT_ID = #{tenantId}
AND ALLOCATION_NO LIKE '%' || #{allocationNo} || '%'
AND ALLOCATION_TYPE = #{allocationType}
AND ALLOCATION_STATUS = #{allocationStatus}
AND ALLOCATION_PERIOD = #{allocationPeriod}
) WHERE rn > #{offset} AND rn <= (#{offset} + #{pageSize})

SELECT COUNT(*)
FROM T_REVENUE_ALLOCATION
WHERE IS_DELETED = 0
AND TENANT_ID = #{tenantId}

    AND ALLOCATION_NO LIKE '%' || #{allocationNo} || '%'


    AND ALLOCATION_TYPE = #{allocationType}


    AND ALLOCATION_STATUS = #{allocationStatus}


    AND ALLOCATION_PERIOD = #{allocationPeriod}
